// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint96 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(amount > 0);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 balanceBefore = c.getBalance(actor);
        assertEq(balanceBefore, amount, "setup failed: balance not recorded");

        vm.prank(actor);
        c.withdrawBalance();

        assertEq(c.getBalance(actor), address(c).balance, "invariant broken: contract ETH must equal user balance sum");
    }
}
